VALUES ('019fe506-359a-7601-92f2-f441cf1dae33', 'Barbell Bench Press', '["CHEST"]'::jsonb, '["SHOULDERS", "ARMS"]'::jsonb, 'A fundamental upper body exercise that targets the chest, shoulders, and triceps. Lie on a flat bench and press the barbell from chest to full extension.', '["Lie flat on bench with feet on floor", "Grip barbell slightly wider than shoulder width", "Lower bar to mid-chest with control", "Press bar up to starting position", "Keep shoulder blades retracted throughout"]'::jsonb, '["Keep your feet flat on the floor for stability", "Maintain a slight arch in your lower back", "Don''t bounce the bar off your chest"]'::jsonb, 'INTERMEDIATE', '["BARBELL", "BENCH"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Bench_Press_-_Medium_Grip/0.jpg', 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

