VALUES ('019fe506-359b-7a6f-82f9-90f196c28c0a', 'Barbell Back Squat', '["LEGS"]'::jsonb, '["CORE", "BACK"]'::jsonb, 'The king of leg exercises. A compound movement that builds overall lower body strength and mass.', '["Position barbell on upper back/traps", "Stand with feet shoulder-width apart", "Descend by breaking at hips and knees", "Lower until thighs are parallel or below", "Drive through heels to return to start"]'::jsonb, '["Keep your chest up and core braced throughout", "Your knees should track over your toes", "Don''t let your knees cave inward"]'::jsonb, 'INTERMEDIATE', '["BARBELL"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Squat/0.jpg', 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

