VALUES ('019fe506-359c-7fb2-942a-65d8449bbd9a', 'Conventional Deadlift', '["BACK", "LEGS"]'::jsonb, '["CORE", "ARMS"]'::jsonb, 'A total body strength builder that primarily targets the posterior chain. One of the most effective exercises for building overall strength.', '["Stand with feet hip-width apart, bar over mid-foot", "Bend down and grip bar just outside legs", "Keep back straight, chest up, core tight", "Drive through heels, extending hips and knees", "Stand fully upright, then lower with control"]'::jsonb, '["Keep the bar close to your body throughout the lift", "Maintain a neutral spine - don''t round your back", "Engage your lats by pulling the bar into your shins"]'::jsonb, 'ADVANCED', '["BARBELL"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Deadlift/0.jpg', 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

