VALUES ('019fe506-359d-71d4-a51e-49d6d3b0e760', 'Pull-Up', '["BACK"]'::jsonb, '["ARMS"]'::jsonb, 'A bodyweight exercise that builds back width and pulling strength.', '["Hang from bar with overhand grip", "Hands slightly wider than shoulders", "Pull yourself up until chin over bar", "Lower yourself with control", "Keep core engaged, avoid swinging"]'::jsonb, '["Pull with your elbows, not just your hands", "Keep your shoulders down and back", "If you can''t do a full pull-up, use resistance bands or do negatives"]'::jsonb, 'INTERMEDIATE', '["PULL_UP_BAR"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Pullups/0.jpg', 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

