VALUES ('019fe506-35a6-7b02-94a3-1ea222589774', 'Dumbbell Chest Fly', '["CHEST"]'::jsonb, '["SHOULDERS"]'::jsonb, 'An isolation exercise that stretches and contracts the chest muscles through a wide arc.', '["Lie flat on bench with dumbbells above chest", "Lower dumbbells out to sides with slight elbow bend", "Feel stretch in chest at bottom", "Squeeze chest to bring dumbbells back together", "Maintain the same elbow bend throughout"]'::jsonb, '["Don''t go too heavy - this is an isolation movement", "Keep a slight bend in your elbows to protect the joint", "Focus on the stretch and squeeze, not the weight"]'::jsonb, 'BEGINNER', '["DUMBBELL", "BENCH"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

