VALUES ('019fe506-35b3-7d27-b390-cdbb73c7cd62', 'Arnold Press', '["SHOULDERS"]'::jsonb, '["ARMS"]'::jsonb, 'A shoulder press variation that rotates through the movement for complete deltoid activation.', '["Start with dumbbells at shoulder level, palms facing you", "Press up while rotating palms to face forward", "At top, palms should face away from you", "Reverse the motion on the way down", "Rotate back to starting position"]'::jsonb, '["The rotation happens as you press, not before", "Keep the movement smooth and controlled", "This exercise hits all three deltoid heads"]'::jsonb, 'INTERMEDIATE', '["DUMBBELL"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Arnold_Dumbbell_Press/0.jpg', 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

