VALUES ('019fe506-35b4-7b32-83e2-6244b1e7d9c0', 'Barbell Shrug', '["BACK"]'::jsonb, '["SHOULDERS"]'::jsonb, 'An isolation exercise for building the trapezius muscles.', '["Stand holding barbell at thigh level", "Shrug shoulders straight up towards ears", "Hold briefly at the top", "Lower with control", "Keep arms straight throughout"]'::jsonb, '["Don''t roll your shoulders - just go straight up and down", "Hold at the top for a brief squeeze", "Keep your neck neutral"]'::jsonb, 'BEGINNER', '["BARBELL"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Shrug/0.jpg', 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

