VALUES ('019fe506-35b5-7334-bbaf-0cfabc29cfbd', 'Tricep Pushdown', '["ARMS"]'::jsonb, '[]'::jsonb, 'A cable exercise that isolates the triceps for arm development.', '["Stand at cable machine with bar or rope attachment", "Grip with palms down, elbows at sides", "Push down until arms are straight", "Squeeze triceps at bottom", "Return with control, keeping elbows fixed"]'::jsonb, '["Keep your elbows pinned to your sides", "Don''t lean into the movement", "Focus on the squeeze at the bottom"]'::jsonb, 'BEGINNER', '["CABLE"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

