VALUES ('019fe506-35b6-73fa-804a-ed95dfa3c92d', 'Overhead Tricep Extension', '["ARMS"]'::jsonb, '[]'::jsonb, 'An isolation exercise that targets the long head of the triceps.', '["Hold dumbbell or cable overhead with both hands", "Lower weight behind head by bending elbows", "Keep upper arms stationary", "Extend arms back to starting position", "Squeeze triceps at top"]'::jsonb, '["Keep your elbows close to your head", "Don''t let your elbows flare out", "Control the weight on the way down"]'::jsonb, 'BEGINNER', '["DUMBBELL"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

