VALUES ('019fe506-35b7-7c5c-92a1-99813a6a8455', 'Skull Crusher', '["ARMS"]'::jsonb, '[]'::jsonb, 'A lying tricep extension that effectively targets all three tricep heads.', '["Lie on bench with barbell or dumbbells extended over chest", "Lower weight towards forehead by bending elbows", "Keep upper arms perpendicular to floor", "Extend arms back to starting position", "Squeeze triceps at top"]'::jsonb, '["Lower to your forehead, not behind your head", "Keep your elbows pointing up, not flaring out", "Use an EZ bar for easier wrist positioning"]'::jsonb, 'INTERMEDIATE', '["EZ_BAR", "BENCH"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

