VALUES ('019fe506-35b8-72ad-901a-b8cc7e665073', 'Close-Grip Bench Press', '["ARMS"]'::jsonb, '["CHEST", "SHOULDERS"]'::jsonb, 'A bench press variation that emphasizes the triceps.', '["Lie on bench and grip bar at shoulder width or narrower", "Lower bar to lower chest with elbows tucked", "Press bar back up to full extension", "Keep elbows close to body throughout", "Focus on tricep engagement"]'::jsonb, '["Hands about shoulder width apart", "Keep elbows at 45 degrees or less", "Don''t go too narrow or you''ll strain your wrists"]'::jsonb, 'INTERMEDIATE', '["BARBELL", "BENCH"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

