VALUES ('019fe506-35b9-7802-85de-b0a9682a8dbc', 'Tricep Dip', '["ARMS"]'::jsonb, '["CHEST", "SHOULDERS"]'::jsonb, 'A bodyweight exercise that targets the triceps using parallel bars or a bench.', '["Grip parallel bars and lift yourself up", "Keep torso upright to emphasize triceps", "Lower body by bending elbows", "Descend until upper arms are parallel to floor", "Push back up to starting position"]'::jsonb, '["Stay upright to keep focus on triceps", "Don''t go too deep if you have shoulder issues", "For bench dips, keep feet on floor or elevated"]'::jsonb, 'INTERMEDIATE', '["BODYWEIGHT"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

