VALUES ('019fe506-35ba-7707-8a53-7d0526921af6', 'Barbell Curl', '["ARMS"]'::jsonb, '[]'::jsonb, 'A fundamental bicep exercise using a barbell for heavy loading.', '["Stand with barbell at thigh level, palms up", "Curl bar up towards shoulders", "Keep elbows stationary at sides", "Squeeze biceps at top", "Lower with control"]'::jsonb, '["Don''t swing your body to lift the weight", "Keep your elbows pinned to your sides", "Use an EZ bar for easier wrist positioning"]'::jsonb, 'BEGINNER', '["BARBELL"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Curl/0.jpg', 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

