VALUES ('019fe506-35bb-7357-8c72-401003939cf2', 'Hammer Curl', '["ARMS"]'::jsonb, '[]'::jsonb, 'A curl variation that targets the brachialis and brachioradialis for arm thickness.', '["Stand with dumbbells at sides, palms facing in", "Curl weights up keeping palms facing each other", "Keep elbows stationary at sides", "Squeeze at top", "Lower with control"]'::jsonb, '["The neutral grip targets different muscles than regular curls", "Don''t swing the weight", "You can curl both arms together or alternate"]'::jsonb, 'BEGINNER', '["DUMBBELL"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Hammer_Curls/0.jpg', 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

