VALUES ('019fe506-35bc-7a3e-9895-70de3b94f943', 'Preacher Curl', '["ARMS"]'::jsonb, '[]'::jsonb, 'A bicep curl performed on a preacher bench for strict isolation.', '["Sit at preacher bench with upper arms on pad", "Hold barbell or dumbbells with arms extended", "Curl weight up towards shoulders", "Squeeze biceps at top", "Lower with control"]'::jsonb, '["Don''t come all the way down to avoid elbow strain", "Keep your upper arms pressed against the pad", "Control the negative portion"]'::jsonb, 'BEGINNER', '["EZ_BAR", "BENCH"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

