VALUES ('019fe506-35bd-742b-b5de-ae7303ccedd6', 'Cable Curl', '["ARMS"]'::jsonb, '[]'::jsonb, 'A bicep curl using cables for constant tension throughout the movement.', '["Stand facing cable machine with handle at low position", "Grip handle with palm up", "Curl handle towards shoulder", "Keep elbow stationary at side", "Lower with control"]'::jsonb, '["The cable provides constant tension unlike free weights", "Try different attachments for variety", "Stand far enough back for proper tension"]'::jsonb, 'BEGINNER', '["CABLE"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

