VALUES ('019fe506-35be-7140-b9fe-bff1822040fc', 'Concentration Curl', '["ARMS"]'::jsonb, '[]'::jsonb, 'A seated single-arm curl that isolates the bicep with strict form.', '["Sit on bench with legs spread", "Brace elbow against inner thigh", "Curl dumbbell towards shoulder", "Squeeze bicep at top", "Lower with control"]'::jsonb, '["This is a great exercise for mind-muscle connection", "Don''t swing - the position forces strict form", "Focus on the peak contraction"]'::jsonb, 'BEGINNER', '["DUMBBELL"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

