VALUES ('019fe506-35bf-7429-9e35-0a0f1062be96', 'Leg Press', '["LEGS"]'::jsonb, '[]'::jsonb, 'A machine exercise for building quad, hamstring, and glute strength.', '["Sit in leg press machine with back against pad", "Place feet shoulder-width apart on platform", "Lower platform by bending knees", "Descend until knees are at 90 degrees", "Press back up without locking knees"]'::jsonb, '["Don''t lock out your knees at the top", "Keep your lower back pressed against the pad", "Foot placement changes muscle emphasis"]'::jsonb, 'BEGINNER', '["MACHINE"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

