VALUES ('019fe506-35c2-7efc-a884-30f32d884431', 'Romanian Deadlift', '["LEGS"]'::jsonb, '["BACK", "CORE"]'::jsonb, 'A hip-hinge movement that targets the hamstrings and glutes.', '["Stand with barbell at thigh level", "Push hips back while lowering bar", "Keep slight bend in knees", "Lower until you feel hamstring stretch", "Drive hips forward to return to start"]'::jsonb, '["Keep the bar close to your body", "Don''t round your back", "Feel the stretch in your hamstrings at the bottom"]'::jsonb, 'INTERMEDIATE', '["BARBELL"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

