VALUES ('019fe506-35c4-7e96-ba37-5c21a0f3d541', 'Seated Calf Raise', '["LEGS"]'::jsonb, '[]'::jsonb, 'A calf exercise that emphasizes the soleus muscle.', '["Sit in seated calf raise machine", "Place balls of feet on platform", "Raise heels as high as possible", "Squeeze calves at top", "Lower heels below platform"]'::jsonb, '["The bent knee position targets the soleus more", "Use a full range of motion", "Pause at the top for a better contraction"]'::jsonb, 'BEGINNER', '["MACHINE"]'::jsonb, 'STRENGTH', 'ISOLATION', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

