VALUES ('019fe506-35c5-7e9d-9bff-db6cca316522', 'Hip Thrust', '["LEGS"]'::jsonb, '["CORE"]'::jsonb, 'A glute-focused exercise that builds strength and size in the posterior chain.', '["Sit on ground with upper back against bench", "Roll barbell over hips", "Drive through heels to lift hips", "Squeeze glutes hard at top", "Lower with control"]'::jsonb, '["Keep your chin tucked throughout", "Push through your heels, not your toes", "Squeeze your glutes hard at the top"]'::jsonb, 'INTERMEDIATE', '["BARBELL", "BENCH"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, 'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Hip_Thrust/0.jpg', 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

