VALUES ('019fe506-35c6-7c41-a8f8-d8a708d074f0', 'Bulgarian Split Squat', '["LEGS"]'::jsonb, '["CORE"]'::jsonb, 'A single-leg squat variation that builds unilateral leg strength.', '["Stand in front of bench with one foot behind on bench", "Hold dumbbells at sides", "Lower back knee towards ground", "Front thigh should reach parallel", "Drive through front foot to stand"]'::jsonb, '["Keep your torso upright", "Front shin should stay relatively vertical", "Start with bodyweight before adding weight"]'::jsonb, 'INTERMEDIATE', '["DUMBBELL", "BENCH"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

