VALUES ('019fe506-35c7-7210-a41a-af15ffc08a58', 'Crunch', '["CORE"]'::jsonb, '[]'::jsonb, 'A fundamental core exercise that targets the rectus abdominis.', '["Lie on back with knees bent", "Place hands behind head or across chest", "Curl shoulders towards hips", "Squeeze abs at top", "Lower with control"]'::jsonb, '["Don''t pull on your neck", "Focus on curling your ribcage towards your pelvis", "Keep your lower back on the ground"]'::jsonb, 'BEGINNER', '["BODYWEIGHT"]'::jsonb, 'STRENGTH', 'ISOLATION', 'REPS_ONLY', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

