VALUES ('019fe506-35c8-70f3-83aa-68a24c0af02a', 'Hanging Leg Raise', '["CORE"]'::jsonb, '[]'::jsonb, 'An advanced core exercise that targets the lower abs.', '["Hang from pull-up bar with arms straight", "Keep legs straight or slightly bent", "Raise legs until parallel to ground or higher", "Lower with control", "Avoid swinging"]'::jsonb, '["Don''t swing - use control", "Focus on tilting your pelvis up", "Bend knees to make it easier"]'::jsonb, 'ADVANCED', '["PULL_UP_BAR"]'::jsonb, 'STRENGTH', 'ISOLATION', 'REPS_ONLY', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

