VALUES ('019fe506-35ca-7c5a-bc2c-1fbb28056716', 'Dead Bug', '["CORE"]'::jsonb, '[]'::jsonb, 'A core stability exercise that teaches proper bracing.', '["Lie on back with arms extended up", "Raise legs with knees bent at 90 degrees", "Lower opposite arm and leg towards ground", "Keep lower back pressed to floor", "Return and alternate sides"]'::jsonb, '["Keep your lower back pressed into the ground", "Move slowly and with control", "This is great for teaching core stability"]'::jsonb, 'BEGINNER', '["BODYWEIGHT"]'::jsonb, 'STRENGTH', 'ISOLATION', 'REPS_ONLY', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

