VALUES ('019fe506-35cb-7080-9e3a-9135726bd29c', 'Mountain Climber', '["CORE"]'::jsonb, '["SHOULDERS", "LEGS"]'::jsonb, 'A dynamic core exercise that also elevates heart rate.', '["Start in high plank position", "Drive one knee towards chest", "Quickly switch legs", "Continue alternating in running motion", "Keep hips level"]'::jsonb, '["Keep your hips down - don''t pike up", "Land on your toes", "Go faster for more cardio, slower for more core focus"]'::jsonb, 'BEGINNER', '["BODYWEIGHT"]'::jsonb, 'CARDIO', 'COMPOUND', 'REPS_ONLY', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

