VALUES ('019fe506-35ce-7bb2-ac34-1cf9758d9bfd', 'Dumbbell Bench Press', '["CHEST"]'::jsonb, '["SHOULDERS", "ARMS"]'::jsonb, 'A chest press using dumbbells for a greater range of motion and balanced development.', '["Lie on flat bench with dumbbells at chest level", "Press dumbbells up until arms are extended", "Lower dumbbells to sides of chest", "Feel stretch in chest at bottom", "Keep feet flat on floor"]'::jsonb, '["Dumbbells allow for a deeper stretch than barbell", "Keep your shoulder blades retracted", "Control the weight on the way down"]'::jsonb, 'BEGINNER', '["DUMBBELL", "BENCH"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

INSERT INTO exercises (id, name, primary_muscles, secondary_muscles, description, instructions, tips, difficulty, equipment_needed, category, exercise_type, tracking_type, video_url, thumbnail_url, source, owner_id, derived_from_id, deprecated, updated_at, deleted_at, revision)
VALUES ('019fe506-35cf-716f-be29-70ea5d1c8a51', 'Chin-Up', '["BACK"]'::jsonb, '["ARMS"]'::jsonb, 'A pull-up variation with underhand grip that emphasizes the biceps.', '["Hang from bar with underhand grip", "Hands shoulder-width apart", "Pull yourself up until chin over bar", "Lower yourself with control", "Keep core engaged"]'::jsonb, '["The underhand grip makes this easier than pull-ups", "Squeeze your biceps at the top", "Don''t swing - use controlled movement"]'::jsonb, 'INTERMEDIATE', '["PULL_UP_BAR"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

INSERT INTO exercises (id, name, primary_muscles, secondary_muscles, description, instructions, tips, difficulty, equipment_needed, category, exercise_type, tracking_type, video_url, thumbnail_url, source, owner_id, derived_from_id, deprecated, updated_at, deleted_at, revision)
VALUES ('019fe506-35d0-7520-b3e9-f4fa230d2e1a', 'Upright Row', '["SHOULDERS"]'::jsonb, '["BACK", "ARMS"]'::jsonb, 'A shoulder exercise that targets the lateral deltoids and traps.', '["Stand holding barbell or dumbbells at thighs", "Pull weight up along body to chin level", "Lead with elbows, keeping them above hands", "Lower with control", "Keep weight close to body"]'::jsonb, '["Don''t go too heavy - this can stress the shoulders", "Stop when elbows reach shoulder height", "Use dumbbells if you have shoulder issues"]'::jsonb, 'INTERMEDIATE', '["BARBELL"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

INSERT INTO exercises (id, name, primary_muscles, secondary_muscles, description, instructions, tips, difficulty, equipment_needed, category, exercise_type, tracking_type, video_url, thumbnail_url, source, owner_id, derived_from_id, deprecated, updated_at, deleted_at, revision)
VALUES ('019fe506-35d1-7779-835a-03fad2a0e63b', 'Front Squat', '["LEGS"]'::jsonb, '["CORE"]'::jsonb, 'A squat variation with the barbell in front, emphasizing the quads and core.', '["Rest barbell on front deltoids with clean grip or crossed arms", "Stand with feet shoulder-width apart", "Descend by breaking at hips and knees", "Keep elbows high and chest up", "Drive through heels to stand"]'::jsonb, '["Keep your elbows up throughout the movement", "Stay more upright than back squat", "Work on wrist mobility for the clean grip"]'::jsonb, 'ADVANCED', '["BARBELL"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

INSERT INTO exercises (id, name, primary_muscles, secondary_muscles, description, instructions, tips, difficulty, equipment_needed, category, exercise_type, tracking_type, video_url, thumbnail_url, source, owner_id, derived_from_id, deprecated, updated_at, deleted_at, revision)
VALUES ('019fe506-35d2-72b8-8b9b-3188abd1a9eb', 'Leg Raise', '["CORE"]'::jsonb, '[]'::jsonb, 'A core exercise performed lying down that targets the lower abs.', '["Lie on back with legs extended", "Place hands under lower back for support", "Raise legs until perpendicular to floor", "Lower legs slowly without touching ground", "Keep lower back pressed down"]'::jsonb, '["Keep your lower back pressed into the floor", "Bend your knees to make it easier", "Don''t let your lower back arch off the ground"]'::jsonb, 'INTERMEDIATE', '["BODYWEIGHT"]'::jsonb, 'STRENGTH', 'ISOLATION', 'REPS_ONLY', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

INSERT INTO exercises (id, name, primary_muscles, secondary_muscles, description, instructions, tips, difficulty, equipment_needed, category, exercise_type, tracking_type, video_url, thumbnail_url, source, owner_id, derived_from_id, deprecated, updated_at, deleted_at, revision)
VALUES ('019fe506-35d3-7f3d-9ab0-d1c26b59e962', 'Reverse Lunge', '["LEGS"]'::jsonb, '["CORE"]'::jsonb, 'A lunge variation stepping backward, easier on the knees.', '["Stand with feet hip-width apart", "Step one foot back into lunge position", "Lower back knee towards ground", "Front thigh should reach parallel", "Push through front foot to return"]'::jsonb, '["Easier on the knees than forward lunges", "Keep your torso upright", "Step back far enough to maintain balance"]'::jsonb, 'BEGINNER', '["BODYWEIGHT"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

INSERT INTO exercises (id, name, primary_muscles, secondary_muscles, description, instructions, tips, difficulty, equipment_needed, category, exercise_type, tracking_type, video_url, thumbnail_url, source, owner_id, derived_from_id, deprecated, updated_at, deleted_at, revision)
VALUES ('019fe506-35d4-7f59-af83-ad2466c8d39c', 'Sumo Deadlift', '["LEGS", "BACK"]'::jsonb, '["CORE"]'::jsonb, 'A deadlift variation with wide stance that emphasizes the quads and adductors.', '["Stand with wide stance, toes pointed out", "Grip bar between legs with arms straight", "Push through legs while keeping chest up", "Stand fully upright", "Lower with control"]'::jsonb, '["Push your knees out over your toes", "Keep your chest up throughout", "This variation is easier on the lower back"]'::jsonb, 'ADVANCED', '["BARBELL"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

INSERT INTO exercises (id, name, primary_muscles, secondary_muscles, description, instructions, tips, difficulty, equipment_needed, category, exercise_type, tracking_type, video_url, thumbnail_url, source, owner_id, derived_from_id, deprecated, updated_at, deleted_at, revision)
VALUES ('019fe506-35d5-7d7f-ae9b-22bbc70bf77d', 'Hack Squat', '["LEGS"]'::jsonb, '[]'::jsonb, 'A machine squat variation that targets the quadriceps.', '["Position yourself in hack squat machine", "Place feet shoulder-width apart on platform", "Lower by bending knees", "Descend until thighs are parallel", "Push back up without locking knees"]'::jsonb, '["The machine provides stability for heavy loading", "Vary foot placement to target different muscles", "Don''t lock out your knees at the top"]'::jsonb, 'BEGINNER', '["MACHINE"]'::jsonb, 'STRENGTH', 'COMPOUND', 'WEIGHT_REPS', NULL, NULL, 'DEFAULT', NULL, NULL, FALSE, 0, NULL, 0);

